# parse chains with strands
chains=[]
with open('/task/input/resources/hg19ToHg38.chr22.over.chain') as f:
    for line in f:
        line=line.strip()
        if not line: continue
        if line.startswith('chain'):
            p=line.split(); c={'p':p,'blocks':[]}; chains.append(c)
            ts,te=int(p[5]),int(p[6]); qs,qe=int(p[10]),int(p[11])
            t=ts if p[4]=='+' else te-1
            q=qs if p[9]=='+' else qe-1
        else:
            p=list(map(int,line.split())); size=p[0]
            c['blocks'].append((t,size,q,size,p[4],p[9]))
            if p[4]=='+': t += size
            else: t -= size
            if p[9]=='+': q += size
            else: q -= size
            if len(p)==3:
                dt,dq=p[1],p[2]
                t = t+dt if p[4]=='+' else t-dt
                q = q+dq if p[9]=='+' else q-dq
print('chain summary:')
for i,c in enumerate(chains):
    p=c['p']; print(i,p[4],p[9],p[5],p[6],p[10],p[11],len(c['blocks']),sum(b[1] for b in c['blocks']))

# source pos->chain info, dest N status
src=pysam.FastaFile('/task/input/resources/GRCh37.chr22.fa.gz')
dst=pysam.FastaFile('/task/input/resources/GRCh38.chr22.fa.gz')
posmap={}
fixed={}
for ci,c in enumerate(chains):
    for t0,size,q0,size2,ts,qs in c['blocks']:
        # walk forward genomic coordinates regardless of strand
        if ts=='+':
            tpos=t0+1; qpos=q0+1
            for k in range(size):
                posmap[tpos+k]=(ci,qpos+k,ts,qs)
        else:
            tpos=t0; qpos=q0
            for k in range(size):
                posmap[tpos-k]=(ci,qpos-k,ts,qs)
        # reference bases at aligned positions
        s=src.fetch('chr22',t0,t0+size).upper(); d=dst.fetch('chr22',q0,q0+size).upper()
        if ts=='+':
            sp=[t0+k+1 for k in range(size)]
        else:
            sp=[t0-k for k in range(size)]
        if qs=='+':
            qp=[q0+k+1 for k in range(size)]
        else:
            qp=[q0-k for k in range(size)]
        for a,b,p,q in zip(s,d,sp,qp):
            if a!='N' and b!='N' and a!=b:
                fixed[p]=(q,a,b,ci)
print('posmap entries',len(posmap),'fixed non-N',len(fixed))

# parse input records, exact fixed overlap and any alt carrier
inp={}
vcf=pysam.VariantFile('/task/input/trio.vcf.gz')
for rec in vcf:
    inp[rec.pos]=rec
fixed_input=sorted(set(fixed)&set(inp))
print('fixed positions with input records',len(fixed_input))
# output records grouped by SRC_POS
out=defaultdict(list)
lv=pysam.VariantFile('/tmp/lift.vcf')
for rec in lv:
    try: sp=rec.info.get('SRC_POS')
    except Exception: sp=None
    if sp is not None:
        out[sp].append(rec)
print('liftover records with SRC_POS',sum(len(v) for v in out.values()))
missing=[]; no_srcref=[]; weird=[]
for p in fixed_input:
    q,sbase,dbase,ci=fixed[p]
    recs=out.get(p,[])
    if not recs:
        missing.append((p,q,sbase,dbase,ci)); continue
    for rec in recs:
        # output position should be q for simple fixed SNP, but if indel may shift
        alleles=[rec.ref]+list(rec.alts or [])
        if sbase not in alleles:
            no_srcref.append((p,q,sbase,dbase,rec.pos,alleles,str(rec))) 
        else:
            ai=alleles.index(sbase)
            carriers=0
            for sample in rec.samples.values():
                gt=sample.get('GT')
                if gt is not None and ai in gt: carriers+=1
            if carriers==0:
                weird.append((p,q,sbase,dbase,rec.pos,alleles,str(rec)))
print('missing output for fixed input pos',len(missing), missing[:10])
print('output missing source ref allele',len(no_srcref))
for x in no_srcref[:20]: print('NOSRC',x)
print('source ref ALT with zero carriers',len(weird))
for x in weird[:20]: print('ZEROCAR',x)

# output records mapped to N dest and chain
n_out=[]
for sp,recs in out.items():
    for rec in recs:
        if rec.pos <= dst.lengths['chr22']:
            b=dst.fetch('chr22',rec.pos-1,rec.pos).upper()
            if b=='N':
                n_out.append((sp,rec.pos,rec.ref,rec.alts,posmap.get(sp)))
print('output records at dest N',len(n_out))
from collections import Counter
print('dest N chain counts',Counter(x[4][0] if x[4] else None for x in n_out))
print('first dest N out',n_out[:10])
