# ---------- GFF ----------
genes={}; tx={}; exons=defaultdict(list); cds=defaultdict(list)
with open('/task/input/resources/GRCh38.chr22.canonical.gff3') as f:
    for line in f:
        if line.startswith('#'): continue
        p=line.rstrip('\n').split('\t')
        if len(p)<9: continue
        attrs=dict(x.split('=',1) for x in p[8].split(';') if '=' in x)
        if p[2]=='gene':
            name=attrs.get('Name')
            if name in panel: genes[name]={'start':int(p[3]),'end':int(p[4]),'strand':p[6],'gid':attrs.get('gene_id')}
        elif p[2] in ('mRNA','transcript'):
            tx[attrs.get('ID')]={'gid':attrs.get('Parent','').replace('gene:',''),'strand':p[6]}
        elif p[2]=='exon': exons[attrs.get('Parent')].append((int(p[3]),int(p[4])))
        elif p[2]=='CDS': cds[attrs.get('Parent')].append((int(p[3]),int(p[4]),p[7]))

fa=pysam.FastaFile('/task/input/resources/GRCh38.chr22.fa.gz')
comp=str.maketrans('ACGTN','TGCAN')
def rc(s): return s.translate(comp)[::-1]

bases='TCAG'; aas='FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG'
codon={}
for i,b1 in enumerate(bases):
    for j,b2 in enumerate(bases):
        for k,b3 in enumerate(bases): codon[b1+b2+b3]=aas[i*16+j*4+k]

models={}
for g,gene in genes.items():
    tids=[t for t,x in tx.items() if x['gid']==gene['gid']]
    if len(tids)!=1: continue
    tid=tids[0]
    segs=sorted(cds.get(tid,[]), key=lambda x:x[0], reverse=(gene['strand']=='-'))
    seq=''; pos2idx={}
    for a,b,ph in segs:
        s=fa.fetch('chr22',a-1,b).upper()
        if gene['strand']=='-': s=rc(s)
        for i,ch in enumerate(s): pos2idx[a+i if gene['strand']=='+' else b-i]=len(seq)+i
        seq+=s
    ex=sorted(exons.get(tid,[]), key=lambda x:x[0], reverse=(gene['strand']=='-'))
    models[g]={'strand':gene['strand'],'start':gene['start'],'end':gene['end'],'cds_seq':seq,'pos2idx':pos2idx,'cds':segs,'exons':ex}

def overlap(a,b,c,d): return not (b<c or a>d)
def splice_cons(pos,reflen,gene):
    m=models.get(gene); strand=m['strand']; ex=m['exons']
    for i in range(len(ex)-1):
        e1,e2=ex[i],ex[i+1]
        if strand=='+':
            donor=(e1[1]+1,e1[1]+2); acceptor=(e2[0]-2,e2[0]-1)
        else:
            donor=(e1[0]-2,e1[0]-1); acceptor=(e2[1]+1,e2[1]+2)
        if overlap(pos,pos+reflen-1,*donor): return 'splice_donor'
        if overlap(pos,pos+reflen-1,*acceptor): return 'splice_acceptor'
    return None

def codon_aa(gene,codon_idx,changes):
    m=models[gene]; c=list(m['cds_seq'][codon_idx*3:codon_idx*3+3])
    for pos,alt in changes:
        idx=m['pos2idx'][pos]; c[idx%3]=alt
    return codon.get(''.join(c),'?')

