with gzip.open('/task/input/resources/popfreq.GRCh38.tsv.gz','rt') as f:
    next(f)
    for line in f:
        p=line.rstrip().split('\t')
        if len(p)>=5: pop[(int(p[1]),p[2],p[3])]=float(p[4])

plugin={}
for r in pysam.VariantFile('/tmp/plugin_good_norm.vcf'):
    if r.alts: plugin[(r.pos,r.ref,r.alts[0])]=r

def qc_ok(pos,ref,alt,pc):
    pr=plugin.get((pos,ref,alt))
    if pr is None: return True
    for s in samples:
        dp=pr.samples[s].get('DP'); gq=pr.samples[s].get('GQ')
        if dp is None or gq is None or dp<10 or gq<20: return False
    if pc==1:
        ad=pr.samples[samples[2]].get('AD')
        if ad is None or len(ad)<2: return False
        if ad[0]+ad[1]==0: return False
        frac=ad[1]/(ad[0]+ad[1])
        if not (0.25<=frac<=0.75): return False
    return True

